	modelId: string,
	storage: CacheStorageLike | null = defaultStorage(),
): Promise<CachedModelInfo> {
	if (!storage) return EMPTY_CACHED_MODEL;
	try {
		return await eachModelEntry(modelId, storage, async (cache, request) => {
