    // compilation. A one-step dummy embedding costs nothing audible.
    await tts("Hello", {
      speaker_embeddings: new Float32Array(1 * 101 * 128),
      num_inference_steps: 1,
      speed: 1.0,
    });
    return tts;
  })();
