/** Drop the downloaded bytes. The next reading will need a fresh download. */
export async function clearSupertonicPack(): Promise<void> {
  await evictModelBundle(SUPERTONIC_BUNDLE_ID, SUPERTONIC_MANIFEST_FILES);
