        activeFile: file.url,
      });
      opts.onProgress?.({
        id,
        phase: "downloading",
        downloadedBytes,
        totalBytes,
        progress: totalBytes > 0 ? downloadedBytes / totalBytes : 0,
        activeFile: file.url,
      });
    });
